import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../redux/formSlice';

export default function StepThree({ prev }) {
  const dispatch = useDispatch();
  const { dob, gender, confirm } = useSelector((state) => state.form);

  return (
    <div>
      <input type="date" value={dob} onChange={(e) => dispatch(updateField({ field: 'dob', value: e.target.value }))} />
      <label>
        <input type="radio" name="gender" value="Male" checked={gender === 'Male'} onChange={(e) => dispatch(updateField({ field: 'gender', value: e.target.value }))} />
        Male
      </label>
      <label>
        <input type="radio" name="gender" value="Female" checked={gender === 'Female'} onChange={(e) => dispatch(updateField({ field: 'gender', value: e.target.value }))} />
        Female
      </label>
      <label>
        <input type="checkbox" checked={confirm} onChange={(e) => dispatch(updateField({ field: 'confirm', value: e.target.checked }))} />
        I confirm my details
      </label>
      <button onClick={prev}>⬅ Prev</button>
      <button disabled={!confirm}>Submit</button>
    </div>
  );
}
